from pathlib import Path
import json,sys
expected=['S1_8K_OK','TEST=C005_P20','AP_READY=1','BSP_ID=00','AP_ACTUAL_ID=01','BAD_CLAIMED_ID=00','BAD_RELEASE=1','BAD_AP_ACQUIRE=1','BAD_DOUBLE_OWNER=1','GOOD_CLAIMED_ID=00','GOOD_ACTUAL_ID=01','GOOD_RELEASE=0','GOOD_AP_ACQUIRE_WHILE=0','GOOD_DOUBLE_OWNER=0','GOOD_AP_ACQUIRE_AFTER=1','AP_DONE=1','DONE']
trace=Path(sys.argv[1]).read_text(encoding='ascii',errors='replace').splitlines();checks={'trace_exact':trace==expected,'two_distinct_apic_ids':all(x in trace for x in ['BSP_ID=00','AP_ACTUAL_ID=01','GOOD_ACTUAL_ID=01']),'bad_claimed_owner_breaks_exclusion':all(x in trace for x in ['BAD_CLAIMED_ID=00','BAD_RELEASE=1','BAD_AP_ACQUIRE=1','BAD_DOUBLE_OWNER=1']),'trusted_release_provenance_preserves_exclusion':all(x in trace for x in ['GOOD_CLAIMED_ID=00','GOOD_RELEASE=0','GOOD_AP_ACQUIRE_WHILE=0','GOOD_DOUBLE_OWNER=0','GOOD_AP_ACQUIRE_AFTER=1']),'h1_proxy':True};out={'format':'C005_P20_EVALUATION_V1','passed':all(checks.values()),'checks':checks,'trace':trace};Path(sys.argv[2]).write_text(json.dumps(out,indent=2)+'\n',encoding='utf-8',newline='\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
